"use client";

import React, { useState } from 'react';
import styled from 'styled-components';
import { ProjectEstimate } from '@/app/ai-estimate/types/projectEstimate';
import Icon from './Icon';
import Modal from '@/components/common/Modal';
import { useToast } from '@/components/common/ToastProvider';
import { useThemeStore } from '@/store/themeStore';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';

const CardWrapper = styled.div`
  background-color: ${({ theme }) => theme.surface1};
  color: ${({ theme }) => theme.text};
  border-radius: 12px;
  overflow: hidden;
  margin: 24px 0;
`;

const Header = styled.div`
  padding: 10px 8px 0 8px;

`;

  const Flex = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 0 0 32px 0;
`;

const Title = styled.h2`
  font-size: 20px;
font-style: normal;
font-weight: 700;
line-height: normal;
`;


const Right = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
`;

const Price = styled.p`
  font-size: 20px;
font-style: normal;
font-weight: 700;
line-height: normal;
letter-spacing: 0.4px;
  margin: 0 0 8px 0;

  span {
    font-size: 0.7em;
    font-weight: normal;
    color: ${({ theme }) => theme.subtleText};
    margin-left: 8px;
  }
`;

const Period = styled.p`
  font-size: 16px;
font-style: normal;
font-weight: 700;
line-height: normal;
letter-spacing: 0.32px;
  color: ${({ theme }) => theme.text};
  margin: 0 0 24px 0;

  .p {
  font-size: 12px;
font-style: normal;
font-weight: 400;
line-height: normal;
letter-spacing: 0.24px;
color: ${({ theme }) => theme.subtleText};
}
`;

const ActionButtons = styled.div`
  display: flex;
  gap: 10px;
  padding-top: 4px;
  border-top: 1px solid ${({ theme }) => theme.border};
  margin: 4px;
`;

const Line = styled.div`
  border-left: 1px solid ${({ theme }) => theme.border};
  `;

const ActionButton = styled.button<{ primary?: boolean }>`
  flex: 1;
  padding: 12px;
  border-radius: 8px;
  border: none;
  background-color: ${({ theme, primary }) => (primary ? theme.accent : 'transparent')};
  color: ${({ theme, primary }) => (primary ? (theme.body) : theme.accent)};
  font-family: Roboto;
  font-size: 14px;
  font-style: normal;
  font-weight: 600;
  line-height: 160%; 
  letter-spacing: 0.28px;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    opacity: 0.8;
  }
`;

const ShareInput = styled.div`
  display: flex;
  gap: 8px;
  margin-top: 8px;

  input {
    flex: 1;
    height: 44px;
    border-radius: 8px;
    border: 1px solid #e5e7eb;
    background: #f9fafb;
    color: #111827;
    padding: 0 12px;
  }

  button {
    height: 44px;
    padding: 0 14px;
    border-radius: 8px;
    background: #2E2E48;
    color: white;
    font-size: 14px;
font-style: normal;
font-weight: 400;
line-height: 160%;
letter-spacing: 0.32px;
  }
`;

interface EstimateCardProps {
  estimate: ProjectEstimate;
}

const EstimateCard: React.FC<EstimateCardProps> = ({ estimate }) => {
  const [openShare, setOpenShare] = useState(false)
  const { success } = useToast()
  const { isDarkMode } = useThemeStore()

  const generatePDF = async () => {
    try {
      // PDF 컨테이너 생성
      const pdfContainer = document.createElement('div');
      pdfContainer.style.padding = '40px';
      pdfContainer.style.width = '780px';
      pdfContainer.style.backgroundColor = 'white';
      pdfContainer.style.position = 'absolute';
      pdfContainer.style.left = '-9999px';

      // PDF 내용 생성
      const content = `
        <div style="font-family: 'Pretendard', sans-serif; color: black;">
          <h1 style="font-size: 24px; text-align: center; margin-bottom: 40px;">견적서</h1>

          <table style="width: 100%; border-collapse: collapse; margin-bottom: 30px;">
            <tr>
              <th style="width: 25%; padding: 8px; border: 1px solid #ddd; background: #f5f5f5;">프로젝트명</th>
              <td style="padding: 8px; border: 1px solid #ddd;">${estimate.project_name}</td>
            </tr>
            <tr>
              <th style="padding: 8px; border: 1px solid #ddd; background: #f5f5f5;">견적 금액</th>
              <td style="padding: 8px; border: 1px solid #ddd;">KRW ${estimate.total_price} (부가세 별도)</td>
            </tr>
            <tr>
              <th style="padding: 8px; border: 1px solid #ddd; background: #f5f5f5;">개발 기간</th>
              <td style="padding: 8px; border: 1px solid #ddd;">${estimate.estimated_period}</td>
            </tr>
          </table>

          <h2 style="font-size: 18px; margin-bottom: 20px;">견적 상세 내역</h2>
          ${estimate.categories.map(category => `
            <div style="margin-bottom: 20px;">
              <h3 style="font-size: 16px; margin-bottom: 10px;">${category.category_name}</h3>
              ${category.sub_categories.map(subCategory => `
                <div style="margin-bottom: 15px;">
                  <h4 style="font-size: 14px; margin-bottom: 10px;">${subCategory.sub_category_name}</h4>
                  <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px;">
                    <tr style="background: #f5f5f5;">
                      <th style="padding: 8px; border: 1px solid #ddd;">항목</th>
                      <th style="padding: 8px; border: 1px solid #ddd;">금액</th>
                      <th style="padding: 8px; border: 1px solid #ddd;">설명</th>
                    </tr>
                    ${subCategory.items.map(item => `
                      <tr>
                        <td style="padding: 8px; border: 1px solid #ddd;">${item.name}</td>
                        <td style="padding: 8px; border: 1px solid #ddd;">${item.price}</td>
                        <td style="padding: 8px; border: 1px solid #ddd;">${item.description}</td>
                      </tr>
                    `).join('')}
                  </table>
                </div>
              `).join('')}
            </div>
          `).join('')}
        </div>
      `;

      pdfContainer.innerHTML = content;
      document.body.appendChild(pdfContainer);

      // HTML을 캔버스로 변환
      const canvas = await html2canvas(pdfContainer, {
        scale: 2,
        useCORS: true,
        logging: false
      });

      // PDF 생성
      const imgWidth = 210; // A4 가로 크기 (mm)
      const pageHeight = 297; // A4 세로 크기 (mm)
      const imgHeight = canvas.height * imgWidth / canvas.width;
      const heightLeft = imgHeight;

      const pdf = new jsPDF('p', 'mm');
      const position = 0;

      // 이미지 추가
      pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, position, imgWidth, imgHeight);

      // PDF 다운로드
      pdf.save('견적서.pdf');

      // 임시 컨테이너 제거
      document.body.removeChild(pdfContainer);
      success('PDF가 생성되었습니다.');
    } catch (error) {
      console.error('PDF 생성 중 오류:', error);
    }
  };

  // estimated_period가 '30주'와 같은 문자열일 경우를 가정하고 숫자만 추출합니다.
  const weekValue = parseInt(estimate.estimated_period);

  // 1개월의 평균 주 수 (30.41일 / 7일)를 사용하여 개월 수를 계산하고 올림 처리합니다.
  const weeksPerMonth = 4.345;
  const monthValue = Math.ceil(weekValue / weeksPerMonth);

  // 최종적으로 보여줄 기간 문자열을 생성합니다.
  const displayPeriod = `(약 ${monthValue}개월)`;

  const shareUrl = typeof window !== 'undefined' ? window.location.href + `?estimate=${encodeURIComponent(estimate.project_name)}` : ''

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl)
      success('링크가 복사되었습니다.')
    } catch {
      // ignore
    }
  }

  return (
    <CardWrapper>
      <Header>
        <Flex>
        <Title>{estimate.project_name}</Title>
        <Right>
        <span><Icon onClick={() => setOpenShare(true)} src={'/ai-estimate/share2_dark.png'} width={36} height={36} /></span>
        <span>
          <Icon 
            onClick={generatePDF}
            src={isDarkMode ? '/ai-estimate/download_dark.png' : '/ai-estimate/download_light.png'} 
            width={36} 
            height={36} 
          />
        </span>
        </Right>

        </Flex>
        <Price>
          KRW {estimate.total_price}
          <span>(부가세 별도)</span>
        </Price>
        {/* 계산된 displayPeriod를 Period 컴포넌트에 적용 */}
        <Period>
          <span style={{marginRight: '4px'}}>{estimate.estimated_period}</span>
          <span className="p">{displayPeriod}</span>
        </Period>
        <ActionButtons>
          <ActionButton>AI 예산 줄이기</ActionButton>
          <Line></Line>
          <ActionButton>AI 맞춤 추천</ActionButton>
        </ActionButtons>
      </Header>

      <Modal open={openShare} title="견적서 공유" onClose={() => setOpenShare(false)} width={520}>
        <div style={{ color: '#A1A1AA', fontSize: 14, marginBottom: 32 }}>공유받은 사용자는 견적 내용을 확인할 수 있습니다.</div>
        <ShareInput>
          <input readOnly value={shareUrl} placeholder="https://aigocorp.com/id..." />
          <button onClick={handleCopy}>링크복사</button>
        </ShareInput>
      </Modal>
    </CardWrapper>
  );
};

export default EstimateCard;
